    svg.appendChild(txt(lbl.label,{x:xS(lbl.i),y:H-margin.bottom+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

