<script>
(function(){
  var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec",
                "Jan","Feb","Mar","Apr"];
  var headline = [1.9,2.1,2.3,2.2,2.0,1.8,1.7,1.9,2.1,2.2,2.3,2.1,
                  1.9,1.8,2.4,2.8];
  var core =     [2.2,2.3,2.4,2.3,2.2,2.1,2.0,2.1,2.2,2.3,2.4,2.3,
                  2.3,2.3,2.3,2.1];
  var n = headline.length;
  var margin = {left:54,right:24,top:18,bottom:46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;
  var minV = 1.5, maxV = 3.2;
  var xS = function(i){ return margin.left + (i/(n-1))*PW; };
  var yS = function(v){ return margin.top + PH - ((v - minV)/(maxV - minV))*PH; };

  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  svg.setAttribute("preserveAspectRatio","xMidYMid meet");

  function el(tag, attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for(var k in attrs) e.setAttribute(k, attrs[k]);
    return e;
  }
  function txt(text, attrs){
    var e = el("text", attrs);
    e.textContent = text;
    return e;
  }

  // Gridlines
  [1.5,2.0,2.5,3.0].forEach(function(v){
    var y = yS(v);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt(v.toFixed(1)+"%",{x:margin.left-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // Axes
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));

  // 2% target reference line
  var refY = yS(2.0);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#2e7d32","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("2.0% BoC TARGET",{x:margin.left+8,y:refY-4,"text-anchor":"start","font-size":"7","fill":"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Hormuz event marker at index 14 (Mar 2026)
  var evX = xS(14);
  svg.appendChild(el("line",{x1:evX,x2:evX,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-dasharray":"2,3","stroke-width":"1","stroke-opacity":"0.5"}));
  svg.appendChild(txt("Hormuz",{x:evX+3,y:margin.top+14,"text-anchor":"start","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(txt("closure",{x:evX+3,y:margin.top+23,"text-anchor":"start","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // X labels: every 3 months
  [0,3,6,9,12,15].forEach(function(i){
    var label = i < 12 ? months[i] + " ''25" : months[i] + " ''26";
    svg.appendChild(txt(label,{x:xS(i),y:margin.top+PH+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // Core line (grey dashed)
  var corePath = "M";
  core.forEach(function(v,i){ corePath += (i===0?"":"L") + xS(i)+","+yS(v); });
  svg.appendChild(el("path",{d:corePath,stroke:"#6b7280","stroke-width":"1.5",fill:"none","stroke-dasharray":"4,3"}));

  // Headline line (slate)
  var headPath = "M";
  headline.forEach(function(v,i){ headPath += (i===0?"":"L") + xS(i)+","+yS(v); });
  svg.appendChild(el("path",{d:headPath,stroke:"#4a5568","stroke-width":"2",fill:"none"}));

  // Gold pill on last headline point
  var lastX = xS(n-1), lastY = yS(headline[n-1]);
  var pillW = 46, pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH/2;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:"3",fill:"#e8a825"}));
  svg.appendChild(txt("2.8%",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Core end label
  var coreLastX = xS(n-1), coreLastY = yS(core[n-1]);
  svg.appendChild(el("circle",{cx:coreLastX,cy:coreLastY,r:3,fill:"#6b7280"}));
  svg.appendChild(txt("Core 2.1%",{x:coreLastX-6,y:coreLastY-6,"text-anchor":"end","font-size":"7.5","fill":"#6b7280","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Legend
  svg.appendChild(el("line",{x1:margin.left+10,x2:margin.left+28,y1:margin.top+8,y2:margin.top+8,stroke:"#4a5568","stroke-width":"2"}));
  svg.appendChild(txt("Headline CPI",{x:margin.left+32,y:margin.top+12,"font-size":"8","fill":"#444","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(el("line",{x1:margin.left+110,x2:margin.left+128,y1:margin.top+8,y2:margin.top+8,stroke:"#6b7280","stroke-width":"1.5","stroke-dasharray":"4,3"}));
  svg.appendChild(txt("Core inflation (median/trim avg)",{x:margin.left+132,y:margin.top+12,"font-size":"8","fill":"#444","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  var container = document.currentScript ? document.currentScript.parentNode : null;
  if(container) container.appendChild(svg);
})();
</script>
