  svg.appendChild(txt("ATH 35,291",{x:athX-4,y:margin.top+18,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

