  svg.appendChild(txt("Jobs +88K",{x:jobsX+3,y:margin.top+28,"text-anchor":"start","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

